<?php

declare(strict_types=1);

namespace Trilobit\Core\Presentation\Finance;

/**
 * Makes the list of rates of tax for
 * Trilobit\Core\Presentation\Finance\TaxRatesPresenter.
 *
 * Generated by the container (see CoreExtension), so that the presenter is
 * handed the one thing it draws rather than the services it is made of.
 */
interface TaxRateListingFactory
{
    public function create(): TaxRateListing;
}
